tools.input_schema_source:
{
    type: 'object',
    properties: {
      fiscal_period_id: {
        type: 'string',
        description: 'Fiscal period UUID; defaults to the period containing today.',
      },
      cost_centre_id: { type: 'string', description: 'Restrict to one cost centre.' },
      include_zero_balances: {
        type: 'boolean',
        description: 'Include accounts whose balance AND movement both net to zero. Default false.',
      },
      detail: { type: 'string', enum: ['summary', 'standard', 'full'] },
      limit: { type: 'integer', minimum: 1, maximum: 500, description: 'Default 200.' },
      cursor: { type: 'string', description: 'next_cursor from the previous page.' },
    },
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const bad = guardCastableArgs(args, { uuid: ['fiscal_period_id', 'cost_centre_id'] });
    if (bad) return bad;

    // Decoded BEFORE the query: a read tool runs with no savepoint, so nothing
    // may throw after the query has run.
    const rawCursor = strArg(args, 'cursor');
    let after: string | null = null;
    if (rawCursor !== undefined) {
      const decoded = decodeCursor(rawCursor, 1);
      if (!decoded) return toolError('invalid cursor');
      after = decoded.parts[0]!;
    }
    const rawDetail = strArg(args, 'detail');
    const detail: DetailLevel = isDetailLevel(rawDetail) ? rawDetail : 'standard';

    const periodId =
      strArg(args, 'fiscal_period_id') ??
      (await getFiscalPeriodIdForDate(ctx.companyId, new Date()));
    if (!periodId) {
      return toolError('No fiscal period covers today. Provide fiscal_period_id explicitly.');
    }

    // companyId from ctx ONLY. The REPORT, never getTrialBalance, because the
    // report is the one place the balanced assertion is computed.
    const report = await getTrialBalanceReport(ctx.companyId, periodId, {
      costCentreId: strArg(args, 'cost_centre_id'),
      includeZeroBalances: args.include_zero_balances === true,
    });

    const sorted = [...report.rows].sort((a, b) => (sortKey(a) < sortKey(b) ? -1 : 1));
    const start = after === null ? 0 : sorted.findIndex((r) => sortKey(r) === after) + 1;
    const limit = clampLimit(args, 200, 500);
    const page = sorted.slice(start, start + limit);
    const last = page[page.length - 1];
    const nextCursor =
      last && start + limit < sorted.length ? encodeCursor({ parts: [sortKey(last)] }) : null;

    const asAt = report.periodEnd || fmtDate(new Date());
    const envelope = buildEnvelope({
      rows: detail === 'summary' ? [] : page,
      // The SERVICE's count of the rows its assertion covers. Taking it from
      // the service rather than from the page is what makes rowsTotal mean
      // "what was asserted over" rather than "what was served".
      rowsTotal: report.accountCount,
      detail,
      as_at: asAt,
      posted_through: await getLedgerPostedThrough(ctx.companyId, asAt),
      next_cursor: nextCursor,
      // Nothing is excluded — the whole point of v2 is that no account is
      // dropped — so the universe is the account count.
      universeTotal: report.accountCount,
      figureBasis: figureBasis('gl.trialbalance.v2'),
    });

    return ok({
      ...envelope,
      fiscal_period_id: report.fiscalPeriodId,
      periodStart: report.periodStart,
      periodEnd: report.periodEnd,
      fiscalYearStart: report.fiscalYearStart,
      accountCount: report.accountCount,
      totalDebit: report.totalDebit,
      totalCredit: report.totalCredit,
      // Straight from the service. Recomputing either of these here is the
      // defect this tool exists to stop repeating.
      difference: report.difference,
      balanced: report.balanced,
      balanceTolerance: BALANCE_TOLERANCE,
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      period_start: { type: 'string', format: 'date', description: 'YYYY-MM-DD. Required.' },
      period_end: { type: 'string', format: 'date', description: 'YYYY-MM-DD. Required.' },
      compare: {
        type: 'string',
        enum: ['prior_period', 'prior_year'],
        description: 'Add a comparative computed on the calendar. Ignored when compare_start/compare_end are given.',
      },
      compare_start: { type: 'string', format: 'date', description: 'Explicit comparative start.' },
      compare_end: { type: 'string', format: 'date', description: 'Explicit comparative end.' },
      cost_centre_id: { type: 'string', description: 'Restrict every figure to one cost centre.' },
      detail: { type: 'string', enum: ['summary', 'standard', 'full'] },
    },
    required: ['period_start', 'period_end'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const periodStart = strArg(args, 'period_start');
    const periodEnd = strArg(args, 'period_end');
    if (!periodStart || !periodEnd) {
      return toolError('period_start and period_end are required (YYYY-MM-DD)');
    }
    // Casts validated BEFORE any query: a read tool runs with no savepoint.
    const bad = guardCastableArgs(args, {
      date: ['period_start', 'period_end', 'compare_start', 'compare_end'],
      uuid: ['cost_centre_id'],
    });
    if (bad) return bad;
    if (periodEnd < periodStart) return toolError('period_end must not precede period_start');

    const compareStart = strArg(args, 'compare_start');
    const compareEnd = strArg(args, 'compare_end');
    const compareMode = strArg(args, 'compare');

    let comparative: PeriodWindow | null = null;
    if (compareStart !== undefined || compareEnd !== undefined) {
      if (compareStart === undefined || compareEnd === undefined) {
        return toolError('compare_start and compare_end must be given together');
      }
      // 'YYYY-MM-DD' compares correctly as text. A comparative overlapping the
      // reporting period is not a comparative, and accepting one produces
      // variances between two windows sharing days.
      if (compareEnd >= periodStart) return toolError('compare_end must be earlier than period_start');
      comparative = { start: compareStart, end: compareEnd };
    } else if (compareMode === 'prior_period') {
      comparative = priorPeriod(periodStart, periodEnd);
    } else if (compareMode === 'prior_year') {
      comparative = priorYearPeriod(periodStart, periodEnd);
    }

    const costCentreId = strArg(args, 'cost_centre_id');
    const rawDetail = strArg(args, 'detail');
    const detail: DetailLevel = isDetailLevel(rawDetail) ? rawDetail : 'standard';

    // SEQUENTIAL: every read runs on the one pg client the request transaction
    // holds, and issuing a query on a client already executing one is
    // deprecated in node-postgres and corrupts the savepoint stack here.
    // companyId from ctx ONLY.
    const current = (await getFinancialFigures(ctx.companyId, periodStart, periodEnd)).period;
    const prior =
      comparative === null
        ? null
        : (await getFinancialFigures(ctx.companyId, comparative.start, comparative.end)).period;
    const coverage = await getClassificationCoverage(
      ctx.companyId, periodStart, periodEnd, costCentreId,
    );
    const postedThrough = await getLedgerPostedThrough(ctx.companyId, periodEnd);

    // From the classifier, not recomputed here: a local copy of the formula is
    // how the page and this tool came to disagree in the first place (B75).
    const operatingProfit = round2(current.operatingProfit);

    // The rows ARE the named unclassified accounts. There is no line-item page
    // here: the statement is a set of totals, and the only thing worth paging
    // is the exception.
    const rows = [
      ...coverage.revenue.accounts.map((a) => ({ ...a, side: 'revenue' as const })),
      ...coverage.expense.accounts.map((a) => ({ ...a, side: 'expense' as const })),
    ];
    const universeTotal =
      coverage.revenue.unclassifiedAccountCount + coverage.expense.unclassifiedAccountCount;

    const envelope = buildEnvelope({
      rows: detail === 'summary' ? [] : rows,
      // The COMPLETE count of unclassified accounts, from the coverage query —
      // not `rows.length`, which is the capped sample. `truncated` then means
      // what it says, and the cap is reported as truncation rather than
      // dressed up as an exclusion.
      rowsTotal: universeTotal,
      detail,
      as_at: periodEnd,
      posted_through: postedThrough,
      // Independently derived: it is the coverage service's own count, not
      // `rowsTotal + excluded` computed back from the numbers being checked.
      // `excludedTotal` is deliberately NOT passed — nothing is excluded here,
      // the list is truncated, and computing it as `universeTotal - rowsTotal`
      // is the anti-pattern CONTRACTS.md §1 names.
      universeTotal,
    });

    const sideOut = (side: CoverageSide) => ({
      total: side.totalAmount,
      classified: side.classifiedAmount,
      unclassified: side.unclassifiedAmount,
      unclassifiedShare: Math.round(share(side) * 10000) / 10000,
      unclassifiedAccountCount: side.unclassifiedAccountCount,
      accounts: side.accounts,
      truncated: side.truncated,
    });

    return ok({
      ...envelope,
      period_start: periodStart,
      period_end: periodEnd,
      cost_centre_id: costCentreId ?? null,
      turnover: round2(current.revenue),
      otherIncome: round2(current.otherIncome),
      costOfSales: round2(current.costOfSales),
      grossProfit: round2(current.grossProfit),
      operatingExpenses: round2(current.operatingExpenses),
      depreciation: round2(current.depreciation),
      operatingProfit,
      /** Finance cost, tax and other expense — the band below operating. */
      otherExpenses: round2(current.otherExpenses),
      netProfit: round2(current.netProfit),
      classificationCoverage: {
        revenue: sideOut(coverage.revenue),
        expense: sideOut(coverage.expense),
        // A single flag a reader can branch on before quoting any band.
        reliable:
          share(coverage.revenue) <= RELIABLE_THRESHOLD
          && share(coverage.expense) <= RELIABLE_THRESHOLD,
      },
      ...(prior === null || comparative === null
        ? {}
        : {
            comparative: {
              period_start: comparative.start,
              period_end: comparative.end,
              turnover: round2(prior.revenue),
              otherIncome: round2(prior.otherIncome),
              costOfSales: round2(prior.costOfSales),
              grossProfit: round2(prior.grossProfit),
              operatingExpenses: round2(prior.operatingExpenses),
              otherExpenses: round2(prior.otherExpenses),
              netProfit: round2(prior.netProfit),
            },
            netProfitVariance: round2(current.netProfit - prior.netProfit),
          }),
      figureBases: {
        turnover: figureBasis('revenue.period.v1'),
        otherIncome: figureBasis('otherincome.period.v1'),
        costOfSales: figureBasis('costofsales.period.v1'),
        otherExpenses: figureBasis('financecost.period.v1'),
        tax: figureBasis('tax.period.v1'),
      },
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      as_at: { type: 'string', format: 'date', description: 'YYYY-MM-DD; defaults to today' },
      compare_date: {
        type: 'string', format: 'date',
        description: 'YYYY-MM-DD. Adds a prior-date column and its own two equity figures.',
      },
      cost_centre_id: { type: 'string', description: 'Restrict every figure to one cost centre.' },
      detail: { type: 'string', enum: ['summary', 'standard', 'full'] },
    },
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    // Casts are validated BEFORE the query: a read tool runs with no savepoint,
    // so a 22007 or 22P02 raised after it aborts the whole request transaction
    // and the registry's own refund write then fails with 25P02.
    const bad = guardCastableArgs(args, {
      date: ['as_at', 'compare_date'],
      uuid: ['cost_centre_id'],
    });
    if (bad) return bad;

    const asAt = strArg(args, 'as_at') ?? fmtDate(new Date());
    const compareDate = strArg(args, 'compare_date');
    if (compareDate !== undefined && compareDate >= asAt) {
      // 'YYYY-MM-DD' compares correctly as text. A comparative dated on or
      // after the reporting date is not a comparative, and silently accepting
      // one produces variances with the sign reversed.
      return toolError('compare_date must be earlier than as_at');
    }
    const costCentreId = strArg(args, 'cost_centre_id');

    const rawDetail = strArg(args, 'detail');
    const detail: DetailLevel = isDetailLevel(rawDetail) ? rawDetail : 'standard';

    // companyId from ctx ONLY.
    const report = await getBalanceSheet(ctx.companyId, asAt, costCentreId, compareDate);
    const equity = await getEquityBases(ctx.companyId, asAt, costCentreId);
    const priorEquity =
      compareDate === undefined
        ? null
        : await getEquityBases(ctx.companyId, compareDate, costCentreId);
    const postedThrough = await getLedgerPostedThrough(ctx.companyId, asAt);

    const rows: BalanceSheetRow[] = [
      ...rowsFor('asset', report.assets),
      ...rowsFor('liability', report.liabilities),
      ...rowsFor('equity', report.equity),
    ];

    const equityResidual = round2(report.totalAssets - report.totalLiabilities);
    // The POSTED equity accounts, not report.totalEquity — which carries the
    // injected retained-earnings plug and therefore equals the residual by
    // construction.
    const equityFromLedger = round2(equity.posted);
    const equityDifference = round2(equityResidual - equityFromLedger);

    const envelope = buildEnvelope({
      rows: detail === 'summary' ? [] : rows,
      rowsTotal: rows.length,
      detail,
      as_at: asAt,
      posted_through: postedThrough,
      // universeTotal is DELIBERATELY ABSENT. There is no wider candidate set
      // here: these rows are PRODUCED by the report, not selected out of a
      // pool, so any universe would have to be synthesized from the very
      // numbers the envelope checks against it — `rowsTotal + excludedRows`.
      // That is the anti-pattern CONTRACTS.md §1 names, and it cannot fail
      // whatever this code did. An absent completeness claim is honest; one
      // that cannot fail is worse than none, because it reads as verification.
    });

    const prior =
      report.compareDate === undefined
        ? {}
        : {
            compare_date: report.compareDate,
            priorTotalAssets: report.priorTotalAssets,
            priorTotalLiabilities: report.priorTotalLiabilities,
            priorTotalEquity: report.priorTotalEquity,
            // Both figures on the prior date too. A comparative that carries
            // only the residual reintroduces the defect on the column nobody
            // checks.
            priorEquityResidual: round2(
              (report.priorTotalAssets ?? 0) - (report.priorTotalLiabilities ?? 0),
            ),
            priorEquityFromLedger: round2(priorEquity?.posted ?? 0),
            priorRetainedEarningsDerived: round2(priorEquity?.derivedRetainedEarnings ?? 0),
          };

    return ok({
      ...envelope,
      totalAssets: report.totalAssets,
      totalLiabilities: report.totalLiabilities,
      totalEquity: report.totalEquity,
      equityResidual,
      equityFromLedger,
      equityDifference,
      // The same number as equityDifference, named for what it actually is.
      retainedEarningsDerived: round2(equity.derivedRetainedEarnings),
      equityReconciles: Math.abs(equityDifference) < EQUITY_TOLERANCE,
      cost_centre_id: costCentreId ?? null,
      // Named separately because they are two different figures with two
      // different owners, and the envelope carries one basis.
      equityFigureBasis: {
        residual: figureBasis('equity.residual.v1'),
        ledger: figureBasis('equity.ledger.v1'),
      },
      ...prior,
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      subledger: {
        type: 'string',
        enum: [...SUBLEDGER_ROLES],
        description: 'Which subledger to reconcile. Required.',
      },
      as_at: {
        type: 'string',
        format: 'date',
        description: 'Reporting date, YYYY-MM-DD. Defaults to today.',
      },
      detail: {
        type: 'string',
        enum: ['summary', 'standard', 'full'],
        description: 'summary = totals only; standard (default) = reconciling items; full = underlying documents.',
      },
      limit: { type: 'integer', minimum: 1, maximum: 500, description: 'detail=full only. Default 200.' },
      cursor: { type: 'string', description: 'next_cursor from the previous page.' },
    },
    required: ['subledger'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const subledger = strArg(args, 'subledger');
    if (!subledger || !(SUBLEDGER_ROLES as readonly string[]).includes(subledger)) {
      // Naming the valid values beats filtering to nothing: an empty
      // reconciliation reads to an agent as "these books agree".
      return toolError(`invalid subledger — expected one of: ${SUBLEDGER_ROLES.join(', ')}`);
    }
    const bad = guardCastableArgs(args, { date: ['as_at'] });
    if (bad) return bad;

    const rawDetail = strArg(args, 'detail');
    const detail: DetailLevel = isDetailLevel(rawDetail) ? rawDetail : 'standard';
    const asAt = strArg(args, 'as_at') ?? fmtDate(new Date());

    // Decode BEFORE the query: a malformed cursor is a caller error, and a read
    // tool runs with no savepoint, so nothing may throw after the query has run.
    const rawCursor = strArg(args, 'cursor');
    let after: string | null = null;
    if (rawCursor !== undefined) {
      const decoded = decodeCursor(rawCursor, 1);
      if (!decoded) return toolError('invalid cursor');
      after = decoded.parts[0]!;
    }

    // companyId from ctx ONLY.
    const rec = await reconcileSubledger(ctx.companyId, subledger as SubledgerRole, asAt);

    const isFull = detail === 'full';
    const allRows: Array<ReconcilingItem | DocumentRow> = isFull
      ? flattenDocuments(rec.reconcilingItems)
      : [...rec.reconcilingItems];
    const rowsTotal = allRows.length;

    let page = allRows;
    let nextCursor: string | null = null;
    if (isFull) {
      const docs = allRows as DocumentRow[];
      const start = after === null ? 0 : docs.findIndex((d) => d.documentId === after) + 1;
      const limit = clampLimit(args, 200, 500);
      page = docs.slice(start, start + limit);
      const last = page[page.length - 1] as DocumentRow | undefined;
      if (last && start + limit < docs.length) {
        nextCursor = encodeCursor({ parts: [last.documentId] });
      }
    }

    const envelope = buildEnvelope({
      rows: detail === 'summary' ? [] : page,
      rowsTotal,
      detail,
      as_at: asAt,
      posted_through: rec.postedThrough ?? NO_LEDGER_READ,
      next_cursor: nextCursor,
      excludedRows: rec.excludedRows,
      // universeTotal is DELIBERATELY ABSENT. There is no wider candidate set
      // here: these rows are PRODUCED by the report, not selected out of a
      // pool, so any universe would have to be synthesized from the very
      // numbers the envelope checks against it — `rowsTotal + excludedRows`.
      // That is the anti-pattern CONTRACTS.md §1 names, and it cannot fail
      // whatever this code did. An absent completeness claim is honest; one
      // that cannot fail is worse than none, because it reads as verification.
      figureBasis: figureBasis(subledger === 'ap' ? 'ap.subledger.v1' : 'ar.subledger.v1'),
    });

    return ok({
      ...envelope,
      subledger: rec.subledger,
      agedTotal: rec.agedTotal,
      subledgerTotal: rec.subledgerTotal,
      subledgerUnavailable: rec.subledgerUnavailable,
      controlAccounts: rec.controlAccounts,
      controlAccountBalance: rec.controlAccountBalance,
      controlAccountAmbiguous: rec.controlAccountAmbiguous,
      difference: rec.difference,
      unexplainedDifference: rec.unexplainedDifference,
      // Named, but deliberately UNOWNED in the figure registry: registering an
      // owner would encode an arbitrary choice of control account as truth and
      // destroy the only thing that can detect the break (FINDINGS C1).
      settlementFlagged: rec.settlementFlagged,
      controlFigureBasis: subledger === 'ap' ? 'ap.control.v1' : 'ar.control.v1',
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      period_start: { type: 'string', format: 'date', description: 'YYYY-MM-DD. Required.' },
      period_end: { type: 'string', format: 'date', description: 'YYYY-MM-DD. Required.' },
      account_codes: {
        type: 'array', items: { type: 'string' },
        description: 'Restrict to these account codes. Preserves runningBalance.',
      },
      account_ids: {
        type: 'array', items: { type: 'string' },
        description: 'Restrict to these account UUIDs. Preserves runningBalance.',
      },
      account_types: {
        type: 'array', items: { type: 'string', enum: [...GL_ACCOUNT_TYPES] },
        description: 'Restrict to these account types. Preserves runningBalance.',
      },
      sources: {
        type: 'array', items: { type: 'string' },
        description: 'Journal sources (e.g. manual, auto_invoice). SUPPRESSES runningBalance.',
      },
      min_amount: {
        type: 'number', minimum: 0,
        description: 'Only lines whose debit or credit is at least this. SUPPRESSES runningBalance.',
      },
      search: {
        type: 'string',
        description: 'Case-insensitive substring of the entry number or description. SUPPRESSES runningBalance.',
      },
      detail: { type: 'string', enum: ['summary', 'standard', 'full'] },
      limit: { type: 'integer', minimum: 1, maximum: 1000, description: 'Default 200, max 1000.' },
      cursor: { type: 'string', description: 'next_cursor from the previous page.' },
    },
    required: ['period_start', 'period_end'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const periodStart = strArg(args, 'period_start');
    const periodEnd = strArg(args, 'period_end');
    if (!periodStart || !periodEnd) {
      return toolError('period_start and period_end are required (YYYY-MM-DD)');
    }
    const accountIds = strArrayArg(args, 'account_ids');
    // Casts are validated BEFORE the query: a read tool runs with no savepoint,
    // so a 22P02 raised after it aborts the whole request transaction.
    const bad = guardCastableArgs(args, { date: ['period_start', 'period_end'] });
    if (bad) return bad;
    if (accountIds?.some((id) => guardCastableArgs({ id }, { uuid: ['id'] }) !== null)) {
      return toolError('invalid account_ids');
    }

    const accountTypes = strArrayArg(args, 'account_types');
    // Refuse an unknown type rather than filtering to nothing: an empty ledger
    // reads to an agent as "this company posted nothing", which is a wrong
    // answer dressed as a right one.
    const unknownType = accountTypes?.find(
      (t) => !(GL_ACCOUNT_TYPES as readonly string[]).includes(t),
    );
    if (unknownType !== undefined) {
      return toolError(`invalid account_types — expected one of: ${GL_ACCOUNT_TYPES.join(', ')}`);
    }

    const rawCursor = strArg(args, 'cursor');
    let after: GeneralLedgerCursor | null = null;
    if (rawCursor !== undefined) {
      const decoded = decodeCursor(rawCursor, CURSOR_PARTS);
      if (!decoded) return toolError('invalid cursor');
      after = {
        accountCode: decoded.parts[0]!,
        date: decoded.parts[1]!,
        // Microsecond precision, carried verbatim. Truncating it to
        // milliseconds re-admits every row inside that millisecond.
        createdKey: decoded.parts[2]!,
        lineId: decoded.parts[3]!,
      };
    }

    const rawDetail = strArg(args, 'detail');
    const detail: DetailLevel = isDetailLevel(rawDetail) ? rawDetail : 'standard';
    // A summary serves totals, so it fetches ONE row rather than a page it will
    // discard — the aggregates ride on any row. Asking for 200 and throwing
    // them away would read a page of a 21,871-line ledger to answer a question
    // about its totals.
    const isSummary = detail === 'summary';

    // companyId from ctx ONLY.
    const page = await getGeneralLedgerLines({
      companyId: ctx.companyId,
      periodStart,
      periodEnd,
      accountCodes: strArrayArg(args, 'account_codes'),
      accountIds,
      accountTypes,
      sources: strArrayArg(args, 'sources'),
      minAmount: numArg(args, 'min_amount'),
      search: strArg(args, 'search'),
      limit: isSummary ? 1 : clampLimit(args, 200, 1000),
      after,
    });

    const nextCursor =
      isSummary || page.next === null
        ? null
        : encodeCursor({
            parts: [page.next.accountCode, page.next.date, page.next.createdKey, page.next.lineId],
          });

    // The universe is the UNFILTERED period. Using the matched count would let
    // the envelope certify a filtered extract as complete — rowsTotal equal to
    // universeTotal, nothing excluded — and the general ledger is the base
    // document of an audit file, where that is the one claim it must never
    // make. The excluded rows are not enumerated (they can be hundreds of
    // thousands and the caller chose to exclude them), so `excludedTotal`
    // carries the count and `truncatedExcludedRows` says the list is shorter.
    const excludedTotal = Math.max(page.universeLineCount - page.lineCount, 0);

    const envelope = buildEnvelope({
      rows: isSummary ? [] : page.lines,
      rowsTotal: page.lineCount,
      detail,
      as_at: periodEnd,
      posted_through: page.postedThrough ?? NO_LEDGER_READ,
      next_cursor: nextCursor,
      universeTotal: page.universeLineCount,
      // Always present, zero included. An absent count and a count of zero are
      // indistinguishable to a reader checking whether they hold the whole
      // ledger, and on an audit document that question must have an answer.
      excludedTotal,
    });

    return ok({
      ...envelope,
      period_start: periodStart,
      period_end: periodEnd,
      totalDebit: page.totalDebit,
      totalCredit: page.totalCredit,
      accountCount: page.accountCount,
      // From the service. Never recomputed from the rows on this page.
      balanced: page.balanced,
      runningBalanceSuppressed: page.runningBalanceSuppressed,
      openingBalances: page.openingBalances,
    });
  }

