      fromDate: strArg(args, 'from_date'),
      toDate: strArg(args, 'to_date'),
      search: strArg(args, 'search'),
      limit: clampLimit(args, 50, 200),
      offset,
    });

    return ok({ invoices: invoices.map(compact), total, offset });
