      },
      min_gap_days: {
        type: 'number',
        description:
          `Shortest run of empty days worth reporting. Default ${DEFAULT_MIN_GAP_DAYS}. `
          + 'Weekends make two-day gaps ordinary, so a low value returns noise.',
      },
      detail: {
        type: 'string',
        enum: ['summary', 'standard', 'full'],
