tools.handler_source:
async (args, ctx) => {
    const planned = await planFromArgs(args, ctx);
    if (!isPlan(planned)) return planned;

    const rawDetail = typeof args.detail === 'string' ? args.detail : undefined;
    const detail: DetailLevel = isDetailLevel(rawDetail) ? rawDetail : 'standard';

    const rows = planned.movable.map((m) => ({
      line_id: m.lineId,
      journal_entry_id: m.journalEntryId,
      entry_number: m.entryNumber,
      entry_date: m.entryDate,
      debit: m.debit,
      credit: m.credit,
      description: m.description,
    }));

    const envelope = buildEnvelope({
      rows: detail === 'summary' ? [] : rows,
      rowsTotal: planned.movable.length,
      detail,
      as_at: planned.impact.window.end,
      posted_through: planned.postedThrough,
      excludedRows: renderSkips(planned).map((s) => ({
        id: s.id,
        reason: s.reason,
        amount: s.amount,
        documentNumber: s.entry_number ?? undefined,
        detail: `${s.entry_date} — journal ${s.journal_entry_id}`,
      })),
      // Its own COUNT over every posted line on the source account in the
      // window, run separately from the page. NOT `rowsTotal + skipped.length`,
      // which would make the identity incapable of failing.
      universeTotal: planned.universeTotal,
      figureBasis: 'gl.reclassification.v1',
    });

    return ok({
      ...envelope,
      source_account: {
        id: planned.source.id, code: planned.source.code, name: planned.source.name,
        type: planned.source.type, subtype: planned.source.subtype,
      },
      target_account: {
        id: planned.target.id, code: planned.target.code, name: planned.target.name,
        type: planned.target.type, subtype: planned.target.subtype,
      },
      warnings: planned.warnings,
      movement: renderMovement(planned),
      periods: renderPeriods(planned),
      // Two full aggregations over the same ledger window — the second with the
      // moved lines projected onto the target — folded by the one owned
      // classifier. Neither is computed from the other, and the `before` side is
      // checked against financialFiguresService: a disagreement arrives as the
      // `basis_disagreement` warning rather than being read as the move's effect.
      profit_and_loss_before: planned.impact.profitAndLossBefore,
      profit_and_loss_after: planned.impact.profitAndLossAfter,
      account_movement: planned.impact.accounts,
      journals: detail === 'full' ? renderJournals(planned) : [],
      journals_total: planned.drafts.length,
    });
  }

async (args, ctx) => {
    const parsed = parseCustomerInvoiceInput(args);
    if (typeof parsed === 'string') return toolError(parsed);
    // Ownership: the customer must belong to the token's company (a plain FK
    // would otherwise accept any company's customer id). Generic error — no
    // existence oracle for foreign ids.
    if (!(await customerBelongsToCompany(ctx.companyId, parsed.customerId))) return toolError(NOT_FOUND);
    try {
      const result = await createDraftCustomerInvoice(ctx.companyId, ctx.userId, {
        clientId: parsed.customerId,
        items: parsed.items,
        invoiceDate: parsed.invoiceDate,
        dueDate: parsed.dueDate,
        taxRate: parsed.taxRate,
        notes: parsed.notes,
      }, mcpPostingOpts(ctx, 'create_draft_invoice'));
      return ok(result);
    } catch (err) {
      // Pre-write only. InvoiceLineValidationError is raised while validating
      // the lines, before the first INSERT, so nothing was written.
      //
      // Everything else must propagate. createDraftCustomerInvoice guards only
      // the invoice-number retry with a savepoint; the line items are inserted
      // OUTSIDE it, so a failing line leaves a committed invoice header with no
      // detail — an AR document carrying a total and nothing to justify it.
      // Swallowing that into toolError() means the handler returns normally,
      // the registry's write-tool savepoint RELEASES instead of rolling back,
      // and the transport's 200 makes bearerPipeline COMMIT the partial row.
      if (err instanceof InvoiceLineValidationError) return toolError(err.message);
      throw err;
    }
  }

async (args, ctx) => {
    const badArg = guardCastableArgs(args, {
      uuid: ['customer_id'],
      date: ['quote_date', 'expiry_date'],
    });
    if (badArg) return badArg;
    const customerName = strArg(args, 'customer_name');
    if (!customerName) return toolError('customer_name is required');
    const items = parseLines(args.items);
    if (!items) return toolError('items must be a non-empty array of {description, unit_price, quantity?}');
    try {
      const quote = await createQuote(
        ctx.companyId,
        {
          customerName,
          clientId: strArg(args, 'customer_id'),
          quoteDate: strArg(args, 'quote_date'),
          expiryDate: strArg(args, 'expiry_date'),
          notes: strArg(args, 'notes'),
          lines: items.map((l) => ({
            description: l.description,
            quantity: l.quantity ?? 1,
            unitPrice: l.unitPrice,
          })),
        },
        ctx.userId,
      );
      return ok(quote);
    } catch (err) {
      // Pre-write only, same reasoning as create_draft_invoice above.
      // createQuote INSERTs the quote header and then loops the lines with no
      // transaction and no savepoint at all, so a failing line leaves a
      // committed header with partial lines unless this throw reaches the
      // registry's savepoint.
      if (err instanceof LineValidationError) return toolError(err.message);
      throw err;
    }
  }

