tools.handler_source:
async (args, ctx) => {
    // Everything the plan does is a READ, and it runs EVERY row-state guard the
    // write path runs. That is what makes the dry run below honest: only the
    // write itself is skipped.
    // The advisory lock on the source account is taken INSIDE planFromArgs,
    // before the candidates are read, and only when this call is going to
    // write. A dry run passes `false`: it writes nothing, and holding a lock
    // that blocks every real batch on the account for the length of a preview
    // would be a denial of service dressed as safety.
    const isDryRun = args.dry_run === true;
    const planned = await planFromArgs(args, ctx, !isDryRun);
    if (!isPlan(planned)) return planned;

    const postingDate = strArg(args, 'posting_date') ?? null;

    // Checked BEFORE the dry-run branch, so both answers are the SAME refusal.
    // Returning a success envelope here while the live call returns a toolError
    // is the forbidden direction by this feature's own criterion — an agent
    // branching on `isError` would get opposite answers from a preview and the
    // call it is previewing.
    if (planned.movable.length === 0) {
      // Pre-write on both paths: the registry audits it with a NULL key, so the
      // agent can retry on the same key once it has fixed its window.
      const reasons = [...new Set(planned.skipped.map((s) => s.reason))];
      return toolError(
        `Nothing to reclassify on ${planned.source.code}: ${planned.skipped.length} candidate `
        + `line${planned.skipped.length === 1 ? '' : 's'} skipped`
        + (reasons.length > 0 ? ` (${reasons.join(', ')})` : '')
        + '. Widen from/to, or pass posting_date to move lines out of closed periods.',
      );
    }

    if (isDryRun) {
      const preview = ok({
        dryRun: true,
        batch_id: null,
        posted: 0,
        would_post_journals: planned.drafts.length,
        would_move_lines: planned.movable.length,
        warnings: planned.warnings,
        movement: renderMovement(planned),
        periods: renderPeriods(planned),
        journals: renderJournals(planned),
        skipped: renderSkips(planned),
        profit_and_loss_before: planned.impact.profitAndLossBefore,
        profit_and_loss_after: planned.impact.profitAndLossAfter,
        account_movement: planned.impact.accounts,
      });
      // Wrote nothing, so it must NOT occupy the idempotency key: the real call
      // that follows carries the same intent and would otherwise be served this
      // preview forever. Free for the same reason.
      preview.wroteNothing = true;
      preview.billable = false;
      return preview;
    }

    // ── Everything below WRITES. No try/catch: a throw must reach the
    // registry's savepoint, which is the only thing that unwinds the journals
    // already posted. Catching here would commit a half-moved account.
    const result = await postReclassBatch(ctx.companyId, ctx.userId, {
      tool: RECLASS_TOOL,
      sourceAccountId: planned.source.id,
      targetAccountId: planned.target.id,
      postingDate,
      idempotencyKey: strArg(args, 'idempotency_key') ?? null,
      drafts: planned.drafts,
      // Stamped as the agent, on every journal. Without it a batch of hundreds
      // of corrections posts as human:<userId> and drops out of
      // list_agent_postings.
      actor: mcpPostingOpts(ctx, RECLASS_TOOL),
    });

    return ok({
      batch_id: result.batchId,
      posted: result.journals.length,
      moved_lines: result.movedLineCount,
      journal_entry_ids: result.journals.map((j) => j.journalEntryId),
      journals: result.journals,
      skipped: renderSkips(planned),
      warnings: planned.warnings,
      movement: renderMovement(planned),
      // Undo route, named in the response and not only in the description.
      reverse_with: 'reverse_journal_entry, once per id in journal_entry_ids',
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      bank_account_id: { type: 'string' },
      file_type: { type: 'string', enum: [...FILE_TYPES] },
      content: { type: 'string', description: 'Raw statement text.' },
      statement_date: { type: 'string', description: 'YYYY-MM-DD — the statement closing date.' },
      bank_format: {
        type: 'string',
        enum: [...BANK_FORMATS],
        description: 'Optional hint (e.g. "fnb", "absa") when CSV auto-detection fails.',
      },
      dry_run: {
        type: 'boolean',
        description: 'Parse and report new/duplicate counts without writing anything.',
      },
      idempotency_key: { type: 'string' },
    },
    required: ['bank_account_id', 'file_type', 'content', 'statement_date', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const bankAccountId = strArg(args, 'bank_account_id');
    const content = strArg(args, 'content');
    const statementDate = strArg(args, 'statement_date');
    const rawFileType = args.file_type;

    if (!bankAccountId) return toolError('bank_account_id is required');
    if (typeof rawFileType !== 'string' || !FILE_TYPES.includes(rawFileType as AgentFileType)) {
      return toolError(`file_type must be one of: ${FILE_TYPES.join(', ')}`);
    }
    if (!content) return toolError('content is required');

    const rawBankFormat = strArg(args, 'bank_format');
    if (rawBankFormat !== undefined && !BANK_FORMATS.includes(rawBankFormat as AgentBankFormat)) {
      return toolError(`bank_format must be one of: ${BANK_FORMATS.join(', ')}`);
    }
    // bank_import_batches.statement_date is NOT NULL — without it the insert
    // fails inside the transaction after parsing has already been paid for.
    if (!statementDate) return toolError('statement_date is required (YYYY-MM-DD)');
    const badArg = guardCastableArgs(args, {
      uuid: ['bank_account_id'],
      date: ['statement_date'],
    });
    if (badArg) return badArg;

    // Ownership. Nothing downstream re-checks the tenant: importParsedTransactions
    // writes whatever bank_account_id it is handed, and migration 446 dropped the
    // FK on bank_import_batches, so a foreign id would land this company's
    // statement in another tenant's account. The error text is deliberately
    // identical to a genuine miss — a distinguishable reply would turn the tool
    // into an existence oracle for accounts the caller cannot read.
    if (!(await bankGlAccountBelongsToCompany(ctx.companyId, bankAccountId))) {
      return toolError(NOT_FOUND);
    }

    if (!(await checkRateLimit(`mcp-bank-import:${ctx.companyId}`, {
      max: IMPORT_MAX_PER_HOUR, windowSecs: 3600,
    }))) {
      return toolError('Import rate limit reached — try again later.');
    }

    try {
      const result = await importStatementForAgent({
        companyId: ctx.companyId,                                  // tenant from ctx ONLY
        bankAccountId,
        fileType: rawFileType as StatementFileType,
        content,
        statementDate,
        bankFormat: rawBankFormat as AgentBankFormat | undefined,  // validated above
        dryRun: args.dry_run === true,
        importedBy: 'mcp:import_bank_statement:v1',
        sourceFilename: 'mcp-import',
      });

      const envelope = ok({
        batch_id: result.batchId,
        dry_run: args.dry_run === true,
        imported: result.imported,
        duplicates: result.duplicates,
        date_range: result.dateRange,
        net_total: result.netTotal,
        parse_errors: result.parseErrors,
      });
      // Nothing was written — every row was already present. The description
      // tells the agent re-sending is safe, so it must also be free; charging
      // for a no-op would contradict the dry_run rule directly above it.
      if (result.batchId === null) envelope.billable = false;
      // A dry run wrote nothing, so it must not occupy the idempotency key —
      // the real import that follows would otherwise be served this preview.
      // Note this is NOT extended to the all-duplicates case above: that one
      // opened no batch but still ran the import path, and freeing its key
      // would let a retry race a concurrent import of the same statement.
      if (args.dry_run === true) envelope.wroteNothing = true;
      return envelope;
    } catch (err) {
      // Pre-write only. StatementNotImportableError is raised while parsing,
      // before importParsedTransactions writes anything, so it is safe to
      // report precisely.
      //
      // NOTE on what the rethrow does and does NOT buy here. Unlike
      // create_draft_invoice/quote below, the import itself is already atomic:
      // importParsedTransactions (bankImportService.ts) wraps the batch row and
      // every bank_transactions insert in withTransaction. So there is no
      // partial-import exposure to close.
      //
      // Since PR #264 withTransaction runs on the ALS-bound request connection
      // inside its own savepoint, so the registry's ROLLBACK TO SAVEPOINT does
      // unwind it. The rethrow (not toolError) is what makes that rollback
      // happen — returning an isError envelope would COMMIT the partial state.
      //
      // The rethrow is kept because a database failure should be recorded by the
      // registry as a failed call (status='error', debit refunded) rather than
      // dressed up as a tidy tool error.
      if (err instanceof StatementNotImportableError) return toolError(err.message);
      throw err;
    }
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      batch_id: { type: 'string' },
      idempotency_key: { type: 'string' },
    },
    required: ['batch_id', 'idempotency_key'],
