        type: 'string',
        description: 'The bank GL account UUID (from bank_accounts_status or list_gl_accounts).',
      },
      from_date: { type: 'string', format: 'date', description: 'Inclusive, YYYY-MM-DD' },
      to_date: { type: 'string', format: 'date', description: 'Inclusive, YYYY-MM-DD' },
      dry_run: {
        type: 'boolean',
        description: 'true reports what would be reversed and writes nothing. Do this first.',
      },
      ...REVERSAL_DATE_PROPERTY,
      idempotency_key: { type: 'string' },
    },
    required: ['bank_account_id', 'from_date', 'to_date', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const bankAccountId = strArg(args, 'bank_account_id');
    const fromDate = strArg(args, 'from_date');
    const toDate = strArg(args, 'to_date');
    if (!bankAccountId) return toolError('bank_account_id is required');
    if (!fromDate) return toolError('from_date is required (YYYY-MM-DD)');
    if (!toDate) return toolError('to_date is required (YYYY-MM-DD)');

    // Every one of these lands in a cast: the id as $n::UUID and both dates as
    // $n::DATE. Guarded here so a typo names the argument instead of surfacing
    // as the registry's generic failure.
    const bad = guardCastableArgs(args, {
      uuid: ['bank_account_id'],
      date: ['from_date', 'to_date'],
    });
    if (bad) return bad;

    if (fromDate > toDate) {
      // Lexical compare is exact for YYYY-MM-DD, and both are already validated
      // as real calendar days. An inverted range silently matches nothing,
      // which would report "0 reversed" and read as "already clean".
      return toolError(`from_date (${fromDate}) is after to_date (${toDate})`);
    }

    // Ownership before anything else. `bank_account_id` becomes a foreign key
    // in the range query; the service does not re-check the tenant.
    if (!(await bankGlAccountBelongsToCompany(ctx.companyId, bankAccountId))) {
      return toolError(NOT_FOUND);
    }

    const reversalDate = strArg(args, 'reversal_date');
    const dryRun = args.dry_run === true;

    // Counted BEFORE fetching, so an oversize range is refused on the true
    // total rather than on a capped page that looks complete.
    const total = await countAllocatedInRange(ctx.companyId, bankAccountId, fromDate, toDate);
    if (total > MAX_RANGE) {
      return toolError(
        `${total} allocated transactions in ${fromDate}..${toDate} exceeds the ${MAX_RANGE} limit. ` +
          'Narrow the date range and reverse in parts.',
      );
    }
    if (total === 0) {
      // Success, not a refusal: a retry, or a second agent arriving after the
      // first finished, is harmless and should read as harmless.
      return ok({
        bank_account_id: bankAccountId, from_date: fromDate, to_date: toDate,
        dry_run: dryRun, reversed: 0, transactions: [],
      });
    }

    const rows = await findAllocatedInRange(
      ctx.companyId, bankAccountId, fromDate, toDate, MAX_RANGE,
    );

    // The preview carries the RULE behind each allocation, because the reason
    // an agent reverses a range is usually that a rule was wrong — and the rule
    // is what it has to fix next, or the next import re-creates all of this.
    const preview = rows.map((r) => ({
      transaction_id: r.id,
      date: r.transactionDate,
      amount: r.amount,
      description: r.description,
      reference: r.reference,
      journal_entry_id: r.journalEntryId,
      allocation_batch_id: r.allocationBatchId,
      created_by_rule: r.allocationRuleName,
    }));

    if (dryRun) {
      return ok({
        bank_account_id: bankAccountId, from_date: fromDate, to_date: toDate,
        dry_run: true,
        would_reverse: rows.length,
        transactions: preview,
        // Named so an agent can go straight to fixing the cause.
        rules_involved: [...new Set(rows.map((r) => r.allocationRuleName).filter(Boolean))],
      });
    }

    // No try/catch, deliberately — see the file header. Rows arrive ordered by
    // id, the same deterministic lock order the allocate and batch-reverse
    // paths use, so this cannot deadlock against a concurrent batch.
    for (const row of rows) {
      // The contra journal is stamped too: without it the agent's own
      // correction posts as human:<userId> and drops out of list_agent_postings,
      // which is the surface a human reviews agent work through.
      await reverseReconciledTransaction(ctx.companyId, row.id, ctx.userId, {
        ...mcpPostingOpts(ctx, REVERSE_RANGE_TOOL),
        ...(reversalDate === undefined ? {} : { reversalDate }),
      });
    }

    return ok({
      bank_account_id: bankAccountId, from_date: fromDate, to_date: toDate,
      dry_run: false,
      reversed: rows.length,
      transactions: preview,
      rules_involved: [...new Set(rows.map((r) => r.allocationRuleName).filter(Boolean))],
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      bank_account_id: { type: 'string', description: 'The bank GL account UUID' },
      as_at: {
        type: 'string',
        format: 'date',
        description: 'The date the balance is stated as at. The journal carries this date, so its fiscal period must exist and be open.',
      },
      amount: {
        type: 'number',
        description: 'The balance as at that date. Negative for an overdrawn account. Zero is refused — it would post nothing and tell you it succeeded.',
      },
      contra_account_id: {
        type: 'string',
        description: 'Optional. The other side of the entry. Defaults to the company\'s Opening Balance Equity account.',
      },
      memo: { type: 'string' },
      idempotency_key: { type: 'string' },
    },
    required: ['bank_account_id', 'as_at', 'amount', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const bankAccountId = strArg(args, 'bank_account_id');
    const explicitContra = strArg(args, 'contra_account_id');
    const asAt = strArg(args, 'as_at');
    if (!bankAccountId) return toolError('bank_account_id is required');
    if (!asAt) return toolError('as_at is required (YYYY-MM-DD)');

    const bad = guardCastableArgs(args, {
      uuid: ['bank_account_id', 'contra_account_id'],
      date: ['as_at'],
    });
    if (bad) return bad;

    const amount = Number(args.amount);
    if (!Number.isFinite(amount)) return toolError('amount must be a number');
    // A zero opening balance posts a journal with two zero lines: it balances,
    // it commits, and it changes nothing — while marking the account as having
    // an opening balance, which then blocks the real one.
    if (amount === 0) {
      return toolError('amount must not be zero — there is nothing to post.');
    }
    if (bankAccountId === explicitContra) {
      // Debiting and crediting the same account nets to nothing but still
      // balances, so nothing downstream would catch it.
      return toolError('contra_account_id must differ from bank_account_id');
    }

    // Ownership for every agent-supplied id, batched, before any write.
    // Neither the service nor the database re-checks the tenant on these
    // foreign keys. The default contra is resolved by ctx.companyId and needs
    // no check — but it is resolved AFTER the ownership and state refusals
    // below, so a refused call never creates the account as a side effect.
    const owned = explicitContra ? [bankAccountId, explicitContra] : [bankAccountId];
    if (!(await accountsBelongToCompany(ctx.companyId, owned))) {
      return toolError(NOT_FOUND);
    }

    const bankAccount = await getAccountById(ctx.companyId, bankAccountId);
    if (!bankAccount) return toolError(NOT_FOUND);
    if (bankAccount.accountSubtype !== 'bank') {
      // Stated plainly: this is the same NULL-subtype trap that makes an
      // account unable to receive a statement import, and the remedy is the
      // same call.
      return toolError(
        `${bankAccount.accountCode} is not a bank account (account_subtype is ` +
          `${bankAccount.accountSubtype ?? 'not set'}). Set it with update_gl_account first.`,
      );
    }

    // Refuse a second opening balance rather than stacking one. Two of these
    // both post, both balance, and the account is then wrong by exactly the
    // first amount with nothing flagging it.
    const existing = await setBankOpeningBalanceMeta.read(ctx.companyId, bankAccountId);
    if (existing.amount !== null && existing.amount !== 0) {
      return toolError(
        `${bankAccount.accountCode} already has an opening balance of ${existing.amount}` +
          `${existing.asAt ? ` as at ${existing.asAt}` : ''}. Reverse that journal before posting another.`,
      );
    }

    // Creating the clearing account is the one write that precedes the
    // journal. It is idempotent (find-or-create on a reserved subtype), so a
    // retry after a later failure finds the same account rather than a second.
    const contra = explicitContra
      ? { id: explicitContra, created: false }
      : await ensureOpeningBalanceEquityAccount(ctx.companyId);
    const contraAccountId = contra.id;

    const amountAbs = Math.abs(Math.round(amount * 100) / 100);
    const bankIsDebit = amount > 0;
    const lines: JournalLineInput[] = [
      {
        glAccountId: bankAccountId,
        debit: bankIsDebit ? amountAbs : 0,
        credit: bankIsDebit ? 0 : amountAbs,
        description: `Opening balance as at ${asAt}`,
      },
      {
        glAccountId: contraAccountId,
        debit: bankIsDebit ? 0 : amountAbs,
        credit: bankIsDebit ? amountAbs : 0,
        description: `Opening balance — ${bankAccount.accountCode}`,
      },
    ];

    // No catch from here on. createJournalEntry validates the period and the
    // balance and refuses BEFORE writing, but postJournalEntry writes — and a
    // `catch → toolError` after that point is audited with a NULL idempotency
    // key, so the agent's retry would post a second opening balance.
    const entry = await createJournalEntry(
      ctx.companyId,
      {
        entryDate: asAt,
        description: strArg(args, 'memo') ?? `Opening balance — ${bankAccount.accountName}`,
        source: 'auto_migration',
        lines,
      },
      ctx.userId,
      mcpPostingOpts(ctx, TOOL),
    );
    await postJournalEntry(ctx.companyId, entry.id, ctx.userId);

    // Written AFTER the posting, so the metadata can never claim an opening
    // balance the ledger does not have. The reverse order would leave the
    // banking screen showing a figure a failed post never created.
    await setBankOpeningBalanceMeta.write(ctx.companyId, bankAccountId, amount, asAt);

    return ok({
      bank_account_id: bankAccountId,
      account_code: bankAccount.accountCode,
      as_at: asAt,
      amount,
      contra_account_id: contraAccountId,
      contra_defaulted: !explicitContra,
      contra_account_created: contra.created,
      journal_entry_id: entry.id,
      posted: true,
    });
  }

async (args, ctx) => {
    const fileName = strArg(args, 'file_name');
    if (!fileName) return toolError('file_name is required');
    if (fileName.length > MAX_FILE_NAME) return toolError(`file_name exceeds ${MAX_FILE_NAME} characters`);

    const mimeType = strArg(args, 'mime_type');
    // enum is advisory — the transport does not validate against inputSchema.
    if (!mimeType || !(ATTACHMENT_MIME_TYPES as readonly string[]).includes(mimeType)) {
      return toolError(`invalid mime_type — expected one of: ${ATTACHMENT_MIME_TYPES.join(', ')}`);
    }

    const content = typeof args.content === 'string' ? args.content : '';
    if (!content) return toolError('content is required');
    const bytes = decodeUploadPayload(content);
    if (!bytes) return toolError('content is not valid base64');

    const selector = pickTxSelector(args);
    if (typeof selector === 'string') return toolError(selector);
    // transaction_id / bank_account_id land as $n::UUID.
    const bad = guardCastableArgs(args, { uuid: ['transaction_id', 'bank_account_id'] });
    if (bad) return bad;
    const resolved = await resolveTxId(selector, ctx.companyId);
    if ('error' in resolved) return toolError(resolved.error);

    const result = await addBankTxAttachment(ctx.companyId, {
      bankTransactionId: resolved.id,
      fileName,
      mimeType: mimeType as AttachmentMime,
      bytes,
      maxBytes: ATTACH_MAX_BYTES,
      uploadedBy: ctx.userId,
    });
    if (!result.ok) {
      switch (result.reason) {
        // Cross-tenant and genuine miss read identically.
        case 'bank_tx_not_found': return toolError(NOT_FOUND);
        case 'type_mismatch': return toolError(`File contents do not match mime_type ${mimeType}`);
        case 'too_large': return toolError(`File exceeds the ${Math.floor(ATTACH_MAX_BYTES / 1024)} KB limit (got ${bytes.length} bytes)`);
        case 'empty': return toolError('content decoded to zero bytes');
      }
    }
    const a = result.attachment;
    return ok({
      attachment_id: a.id,
      transaction_id: a.bankTransactionId,
      file_name: a.fileName,
      file_size: a.fileSize,
      mime_type: a.mimeType,
      created_at: a.createdAt,
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      reconciliation_id: {
        type: 'string',
        description: 'Id from list_bank_reconciliations. Must be in_progress.',
      },
      dry_run: { type: 'boolean' },
      idempotency_key: { type: 'string' },
    },
    required: ['reconciliation_id', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const reconId = strArg(args, 'reconciliation_id');
    if (!reconId) return toolError('reconciliation_id is required');
    const bad = guardCastableArgs(args, { uuid: ['reconciliation_id'] });
    if (bad) return bad;
    const dryRun = args.dry_run === true;

    try {
      const result = await cancelReconciliation(ctx.companyId, reconId, ctx.userId, { dryRun });
      return {
        ...ok({
          reconciliation_id: reconId,
          cancelled: !dryRun,
          dry_run: dryRun,
          reverted_matches: result.revertedMatches,
          released_transactions: result.releasedTransactions,
        }),
        // A dry run wrote nothing, so it must not burn the idempotency key —
        // the real call that follows carries the same key and would otherwise
        // replay this preview forever.
        ...(dryRun ? { wroteNothing: true, billable: false } : {}),
      };
    } catch (err) {
      // A refusal is raised before anything is written (or after the service's
      // own transaction has already rolled back), so returning it as a tool
      // error leaves nothing half-applied. Anything else MUST rethrow: the
      // registry's savepoint unwinds on a throw only, and an isError result
      // would commit a partial cancel.
      if (err instanceof ReconciliationNotCancellableError) return toolError(err.message);
      throw err;
    }
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      name: { type: 'string', description: 'e.g. "VAT", "Payroll", "Financial Statements".' },
      reporting_tag: { type: 'string', description: 'Optional grouping label used by practice reports.' },
      sort_order: { type: 'number' },
      idempotency_key: { type: 'string' },
    },
    required: ['name', 'idempotency_key'],
    additionalProperties: false,
