tools.handler_source:
async (args, ctx) => {
    const name = strArg(args, 'name');
    if (!name) return toolError('name is required');

    // Pre-check so the agent gets the clashing id back and can reuse it,
    // rather than only a 23505 it has to look up. The index added in migration
    // 527 is what actually makes this safe under concurrency.
    const existing = await listJobCategories(ctx.companyId, true);
    const clash = existing.find((c) => c.name.trim().toLowerCase() === name.toLowerCase());
    if (clash) {
      return toolError(`A job category named "${clash.name}" already exists (id ${clash.id}).`);
    }

    const sortOrderRaw = Number(args.sort_order);
    try {
      const category = await createJobCategory(ctx.companyId, {
        name,
        reportingTag: strArg(args, 'reporting_tag'),
        sortOrder: Number.isFinite(sortOrderRaw) ? Math.floor(sortOrderRaw) : undefined,
      });
      return ok({
        id: category.id,
        name: category.name,
        reporting_tag: category.reportingTag,
        is_active: category.isActive,
        next_step: 'Add at least one work item with create_work_item before logging time against this category.',
      });
    } catch (err) {
      if (isUniqueViolation(err)) {
        return toolError(`A job category named "${name}" already exists.`);
      }
      return toolError(safeErrorText(err, 'Could not create the job category.'));
    }
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      category_id: { type: 'string', description: 'Job category UUID from list_job_categories.' },
      name: { type: 'string', description: 'e.g. "VAT201 submission", "Monthly processing".' },
      default_billable: { type: 'boolean', description: 'Defaults to true.' },
      sort_order: { type: 'number' },
      idempotency_key: { type: 'string' },
    },
    required: ['category_id', 'name', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const guard = guardCastableArgs(args, { uuid: ['category_id'] });
    if (guard) return guard;

    const categoryId = strArg(args, 'category_id');
    const name = strArg(args, 'name');
    if (!categoryId) return toolError('category_id is required');
    if (!name) return toolError('name is required');

    // The category id comes from the agent, so confirm it belongs to THIS
    // company before the service call, and refuse with the shared NOT_FOUND —
    // a distinct "belongs to another company" reply would be an existence
    // oracle (src/lib/mcp/AGENTS.md). createWorkItem re-checks too; this is the
    // layer that controls the wording.
    const categories = await listJobCategories(ctx.companyId, true);
    if (!categories.some((c) => c.id === categoryId)) return toolError(NOT_FOUND);

    // Pre-check so the agent gets the clashing id back; migration 527's index
    // is what holds under concurrency. An unnoticed second "VAT201 submission"
    // would split every service-mix report thereafter.
    const siblings = await listWorkItems(ctx.companyId, categoryId, true);
    const clash = siblings.find((w) => w.name.trim().toLowerCase() === name.toLowerCase());
    if (clash) {
      return toolError(`A work item named "${clash.name}" already exists in this category (id ${clash.id}).`);
    }

    const sortOrderRaw = Number(args.sort_order);
    try {
      const item = await createWorkItem(ctx.companyId, categoryId, {
        name,
        defaultBillable: args.default_billable === undefined ? true : args.default_billable === true,
        sortOrder: Number.isFinite(sortOrderRaw) ? Math.floor(sortOrderRaw) : undefined,
      });
      return ok({
        id: item.id,
        category_id: item.categoryId,
        name: item.name,
        is_active: item.isActive,
        default_billable: item.defaultBillable,
      });
    } catch (err) {
      if (isUniqueViolation(err)) {
        return toolError(`A work item named "${name}" already exists in this category.`);
      }
      // The service's own ownership check races the one above (a category
      // deactivated or deleted in between). Keep the shared wording.
      if (err instanceof Error && err.message === 'job category not found') {
        return toolError(NOT_FOUND);
      }
      return toolError(safeErrorText(err, 'Could not create the work item.'));
    }
  }

async (args, ctx) => {
    const guard = guardCastableArgs(args, {
      uuid: ['practice_client_id', 'job_category_id', 'work_item_id'],
      date: ['entry_date'],
    });
    if (guard) return guard;

    const entryDate = strArg(args, 'entry_date');
    const practiceClientId = strArg(args, 'practice_client_id');
    const jobCategoryId = strArg(args, 'job_category_id');
    const workItemId = strArg(args, 'work_item_id');
    const taskDescription = strArg(args, 'task_description');
    if (!entryDate) return toolError('entry_date is required');
    if (!practiceClientId) return toolError('practice_client_id is required');
    if (!jobCategoryId) return toolError('job_category_id is required');
    if (!workItemId) return toolError('work_item_id is required');
    if (!taskDescription) return toolError('task_description is required');
    if (taskDescription.length > 500) return toolError('task_description must be 500 characters or fewer');

    // Range-check the value AS STORED. `hours` is NUMERIC(6,2), so 0.004 is
    // > 0 here but 0.00 in the column; the service applies the same rule, and
    // the tool has to agree or a dry run would pass what the write refuses.
    const hours = roundHours(Number(args.hours));
    if (!Number.isFinite(hours) || hours <= 0 || hours > 24) {
      return toolError('hours must be a number greater than 0 and at most 24 (stored to 2 decimals, so anything under 0.005 rounds to zero and is refused)');
    }

    const today = new Date().toISOString().slice(0, 10);
    if (entryDate > today) return toolError('entry_date cannot be in the future');

    const floor = backdateFloor(today);
    if (entryDate < floor && args.allow_backdating !== true) {
      return toolError(
        `entry_date ${entryDate} is before ${floor}. Without allow_backdating this tool books only into the ` +
        `current or previous month: an older period has usually been invoiced and reported on, every practice ` +
        `report windows on entry_date so the row would restate it, and the rate applied is the one effective ` +
        `on that date. Re-send with allow_backdating: true if that is intended.`,
      );
    }

    const billable = args.billable === undefined ? true : args.billable === true;

    // dry_run parity: every guard the live path runs, run here too. A dry run
    // that skips the ownership/active checks would greenlight a call the real
    // one then refuses.
    if (args.dry_run === true) {
      try {
        await validateClientCategoryWorkItem(
          ctx.companyId, practiceClientId, jobCategoryId, workItemId,
        );
      } catch (err) {
        return toolError(safeErrorText(err, 'The client, category or work item is not usable.'));
      }
      const rate = await resolveRate(ctx.companyId, ctx.userId, practiceClientId, entryDate);
      return {
        ...ok({
          dry_run: true,
          would_create: {
            entry_date: entryDate, hours, billable,
            applied_rate: rate,
            line_total: lineTotalFor(hours, rate),
          },
          note: rate == null
            ? 'No staff rate is configured for this user and client on this date; the entry would be created with no rate and no line total.'
            : 'Validation passed. Re-send without dry_run, reusing this idempotency_key, to write it.',
        }),
        wroteNothing: true,
      };
    }

    try {
      const entry = await createPracticeEntry(ctx.companyId, ctx.userId, {
        entryDate,
        hours,
        practiceClientId,
        jobCategoryId,
        workItemId,
        taskDescription,
        notes: strArg(args, 'notes') ?? null,
        billable,
        // Never from args — see the file header.
        origin: 'assisted',
      });
      return ok({
        id: entry.id,
        entry_date: entry.entryDate,
        hours: entry.hours,
        status: entry.status,
        billable: entry.billable,
        applied_rate: entry.appliedRate,
        line_total: entry.lineTotal,
      });
    } catch (err) {
      return toolError(safeErrorText(err, 'Could not log the time entry.'));
    }
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      entry_ids: {
        type: 'array',
        items: { type: 'string' },
        description: `Time entry UUIDs from list_time_entries. Max ${MAX_SUBMIT_IDS}.`,
      },
      dry_run: { type: 'boolean', description: 'Report which ids would be submitted, without writing.' },
      idempotency_key: { type: 'string' },
    },
    required: ['entry_ids', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const raw = args.entry_ids;
    if (!Array.isArray(raw) || raw.length === 0) {
      return toolError('entry_ids is required and must be a non-empty array');
    }
    if (raw.length > MAX_SUBMIT_IDS) {
      return toolError(`entry_ids accepts at most ${MAX_SUBMIT_IDS} ids per call`);
    }
    const listGuard = guardUuidList(raw, (i) => `entry_ids[${i}]`);
    if (listGuard) return listGuard;

    const ids = [...new Set(raw as string[])].filter((id) => UUID_RE.test(id));

    // Resolve what is actually submittable BEFORE writing, so the reply can
    // name the skipped ids instead of just returning a count that silently
    // disagrees with what the agent asked for.
    //
    // Looked up BY ID, not by listing the user's entries and filtering: a staff
    // member with years of history would otherwise have their whole timesheet
    // pulled into memory on every call, dry runs included, to check at most 200
    // ids. The lookup carries the same company + user scope the UPDATE does.
    const statuses = await getEntryStatusesByIds(ctx.companyId, ids, ctx.userId);
    const submittableSet = new Set(ids.filter((id) => statuses.get(id) === 'draft'));
    const submittable = [...submittableSet];
    const skipped = ids
      .filter((id) => !submittableSet.has(id))
      .map((id) => ({
        id,
        reason: statuses.has(id)
          ? `status is '${statuses.get(id)!}', not 'draft'`
          : 'not found, or not this user\'s entry',
      }));

    if (args.dry_run === true) {
      return {
        ...ok({ dry_run: true, would_submit: submittable, skipped }),
        wroteNothing: true,
      };
    }

    if (submittable.length === 0) {
      return toolError(
        `None of the supplied ids are draft entries belonging to this user. ${JSON.stringify(skipped)}`,
      );
    }

    try {
      // Scoped to ctx.userId: submitPracticeEntries is otherwise company-wide,
      // which would let an agent push a colleague's drafts into approval.
      const count = await submitPracticeEntries(ctx.companyId, submittable, ctx.userId);
      return ok({ submitted: count, submitted_ids: submittable, skipped });
    } catch (err) {
      return toolError(safeErrorText(err, 'Could not submit the time entries.'));
    }
  }

async (args, ctx) => {
    const type = strArg(args, 'type');
    if (!type || !TYPES.includes(type as (typeof TYPES)[number])) {
      return toolError(`type must be one of: ${TYPES.join(', ')}`);
    }
    const creditDate = strArg(args, 'credit_date');
    if (!creditDate) return toolError('credit_date is required (YYYY-MM-DD)');

    const bad = guardCastableArgs(args, {
      uuid: ['client_id', 'supplier_id', 'customer_invoice_id', 'supplier_invoice_id'],
      date: ['credit_date'],
    });
    if (bad) return bad;

    // Non-positive subtotals invert the note's GL at approve — a negative
    // credit note is an invoice wearing the wrong document type, and it would
    // pass every downstream balance check while moving the ledger the wrong
    // way. The REST route guards its line items for the same reason.
    const subtotal = Number(args.subtotal);
    if (!Number.isFinite(subtotal) || subtotal <= 0) {
      return toolError('subtotal must be a positive number (net of VAT)');
    }

    let taxRate: number | undefined;
    if (args.tax_rate !== undefined && args.tax_rate !== null) {
      taxRate = Number(args.tax_rate);
      if (!Number.isFinite(taxRate) || taxRate < 0 || taxRate > 100) {
        return toolError('tax_rate must be between 0 and 100');
      }
    }

    const clientId = strArg(args, 'client_id');
    const supplierId = strArg(args, 'supplier_id');
    const customerInvoiceId = strArg(args, 'customer_invoice_id');
    const supplierInvoiceId = strArg(args, 'supplier_invoice_id');

    // Refuse the cross-type combinations here rather than letting them through
    // as NULLs: a customer note carrying supplier_invoice_id would be created
    // successfully and then approve into a journal with nothing to apply to.
    if (type === 'customer' && (supplierId || supplierInvoiceId)) {
      return toolError('A customer credit note cannot carry supplier_id or supplier_invoice_id');
    }
    if (type === 'supplier' && (clientId || customerInvoiceId)) {
      return toolError('A supplier credit note cannot carry client_id or customer_invoice_id');
    }

    // Tenant AND counterparty ownership, before the first write. Neither the
    // service nor the database re-checks either one — every id below is a bare
    // foreign key with no (id, company_id) constraint — so this is the only
    // thing standing between a foreign UUID and a cross-tenant document, or a
    // note that pays down the wrong counterparty's invoice at approve.
    const linkError = await validateCreditNoteLinks(ctx.companyId, {
      type: type as (typeof TYPES)[number],
      clientId,
      supplierId,
      customerInvoiceId,
      supplierInvoiceId,
    });
    if (linkError) return toolError(linkError);

    // Natural-key dedupe, agent-boundary only.
    //
    // The registry replays only on the SAME idempotency key, and an agent whose
    // call times out routinely retries with a fresh one — so nothing otherwise
    // stops an identical second draft. Refusing beats warning: two drafts are
    // harmless until both are approved, and then they are two journals and two
    // credits against one invoice, which is precisely the pair nobody notices.
    // The reply names the existing note so the agent can approve THAT one, and
    // a genuinely distinct second note differs in date, amount or reason.
    //
    // Deliberately not in the service: the REST route backs a form where a
    // person can see their own draft list, and refusing there would obstruct a
    // legitimate duplicate. The blind retry is an agent problem.
    const taxRateForTotal = taxRate ?? 15;
    const total = Math.round(subtotal * (1 + taxRateForTotal / 100) * 100) / 100;
    const duplicate = await findOpenDuplicateDraft(
      ctx.companyId,
      {
        type: type as (typeof TYPES)[number],
        clientId, supplierId, customerInvoiceId, supplierInvoiceId,
        creditDate,
      },
      total,
    );
    if (duplicate) {
      return toolError(
        `An identical draft credit note already exists (id ${duplicate}) for the same counterparty, `
        + 'date and amount. Approve that one with approve_credit_note, or change the date, amount or '
        + 'reason if this is genuinely a second credit.',
      );
    }

    const note = await createCreditNote(
      ctx.companyId,
      {
        type: type as (typeof TYPES)[number],
        clientId,
        supplierId,
        customerInvoiceId,
        supplierInvoiceId,
        creditDate,
        reason: strArg(args, 'reason'),
        subtotal,
        taxRate,
      },
      ctx.userId,
      // A draft note posts no journal, so the document row is the only place
      // the actor can be recorded until approval (migration 531).
      mcpPostingOpts(ctx, 'create_credit_note'),
    );

    return ok({
      id: note.id,
      credit_note_number: note.creditNoteNumber,
      type: note.type,
      status: note.status,
      subtotal: note.subtotal,
      tax_rate: note.taxRate,
      tax_amount: note.taxAmount,
      total_amount: note.totalAmount,
    });
  }

