tools.input_schema_source:
{
    type: 'object',
    properties: {
      month: { type: 'number', description: 'Calendar month, 1-12.' },
      year: { type: 'number', description: 'Calendar year, e.g. 2026.' },
      ...MUTATION_ARG_SCHEMA,
    },
