tools.handler_source:
async (args, ctx) => {
    const periodId = strArg(args, 'fiscal_period_id');
    if (!periodId) return toolError('fiscal_period_id is required');
    const bad = guardCastableArgs(args, { uuid: ['fiscal_period_id'] });
    if (bad) return bad;
    const dryRun = args.dry_run === true;

    // Every refusal is answered from a READ, so the service call can rethrow.
    const period = await getFiscalPeriodById(ctx.companyId, periodId);
    if (!period) return toolError(NOT_FOUND);
    if (period.status === 'locked') {
      return toolError(`${period.periodName} is locked and cannot be reopened`);
    }
    if (period.status === 'open') return toolError(`${period.periodName} is already open`);

    if (dryRun) {
      return {
        ...ok({
          fiscal_period_id: periodId, period_name: period.periodName,
          status: period.status, reopened: false, dry_run: true,
        }),
        ...DRY,
      };
    }

    const reopened = await reopenPeriod(ctx.companyId, periodId);
    return ok({
      fiscal_period_id: periodId,
      period_name: reopened.periodName,
      status: reopened.status,
      reopened: true,
      dry_run: false,
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      fiscal_year: {
        type: 'number',
        description: 'The fiscal_year label from list_fiscal_periods, e.g. 2027.',
      },
      ...MUTATION_ARG_SCHEMA,
    },
    required: ['fiscal_year', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const year = args.fiscal_year;
    if (!Number.isInteger(year)) return toolError('fiscal_year must be a whole number');
    const dryRun = args.dry_run === true;

    // No try/catch: every refusal this service can raise comes back as a typed
    // result BEFORE it writes, and anything it THROWS comes from inside its
    // write transaction. Catching that and returning a tool error would commit
    // a half-posted year-end and free the key for a second attempt.
    const result = await closeFiscalYear(ctx.companyId, String(year), ctx.userId, { dryRun });

    if ('error' in result) {
      if (result.error === 'open_periods') {
        return toolError(
          `Fiscal year ${year} has ${result.count} open period`
          + `${result.count === 1 ? '' : 's'}: `
          + `${result.openPeriods.map((p) => p.periodName).join(', ')}. `
          + 'Close each of them with close_fiscal_period first. Nothing was posted.',
        );
      }
      if (result.error === 'period_range_mismatch') {
        return toolError(
          `Fiscal year ${year}'s periods run ${result.actual.startDate} to ${result.actual.endDate}, `
          + `but this company's financial year starts in month ${result.startMonth}, so `
          + `FY${year} is really ${result.expected.startDate} to ${result.expected.endDate}. `
          + 'Closing the periods as they stand would roll the wrong twelve months into retained '
          + 'earnings and then LOCK them, and nothing would look wrong afterwards because the '
          + 'journal balances either way. Nothing was posted. '
          + 'THE FIX IS NOT THIS TOOL. The periods themselves are misaligned with the financial '
          + 'year, and the year-end close is downstream of that: re-dating live fiscal periods is '
          + 'a data correction that needs a person to decide it, not something a close should do '
          + 'on the way past. Call list_fiscal_periods and read `alignment` — when `aligned` is '
          + 'false, that is the thing to fix, and this close will work once it is.',
        );
      }
      if (result.error === 'no_fiscal_period') {
        return toolError(
          `No fiscal period covers ${result.entryDate}, where the closing journal would be dated. `
          + 'Posting it without one would leave it outside the trial balance, the VAT201 and the '
          + 'AFS permanently. Nothing was posted.',
        );
      }
      if (result.error === 'ambiguous_retained_earnings') {
        return toolError(
          `More than one account could be retained earnings (${result.accountCodes.join(', ')}) `
          + 'so the close refuses rather than breaking the tie. Posting a year of trading into '
          + 'the wrong equity account and then locking every period behind it is not recoverable '
          + 'in place. Leave the role on exactly one account with update_gl_account. '
          + 'Nothing was posted.',
        );
      }
      if (result.error === 'no_retained_earnings') {
        return toolError(
          'No account carries the retained_earnings system role for this company. Create one with '
          + 'create_gl_account, or set the subtype on the existing equity account with '
          + 'update_gl_account. Nothing was posted.',
        );
      }
      return toolError(`Fiscal year ${year} has no periods. Nothing was posted.`);
    }

    if ('dryRun' in result) {
      return {
        ...ok({
          fiscal_year: year,
          dry_run: true,
          net_income: result.netIncome,
          would_post: {
            entry_number: result.preview.entryNumber,
            entry_date: result.preview.entryDate,
            description: result.preview.description,
            total_debit: result.preview.totalDebit,
            total_credit: result.preview.totalCredit,
            lines: result.preview.lines.map((l) => ({
              account_id: l.accountId,
              account_code: l.accountCode,
              account_name: l.accountName,
              debit: l.debit,
              credit: l.credit,
            })),
          },
          would_lock_every_period_in_year: true,
        }),
        ...DRY,
      };
    }

    return ok({
      fiscal_year: year,
      dry_run: false,
      net_income: result.netIncome,
      journal_entry_id: String(result.closingEntry.id),
      entry_number: String(result.closingEntry.entry_number),
      periods_locked: true,
      message: result.message,
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      bank_account_id: {
        type: 'string',
        description: 'The bank GL account id, from bank_accounts_status or list_gl_accounts.',
      },
      statement_date: {
        type: 'string',
        format: 'date',
        description: 'YYYY-MM-DD. The GL balance is taken up to and including this date.',
      },
      statement_balance: {
        type: 'number',
        description: 'The closing balance printed on the bank statement. Negative if overdrawn.',
      },
      auto_match: {
        type: 'boolean',
        description: 'Run auto-matching after starting. Default true.',
      },
      complete: {
        type: 'boolean',
        description:
          'Complete the reconciliation if it balances exactly. Default false. '
          + 'Completing marks every matched transaction reconciled and closes the session.',
      },
      ...MUTATION_ARG_SCHEMA,
    },
    required: ['bank_account_id', 'statement_date', 'statement_balance', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    const bankAccountId = strArg(args, 'bank_account_id');
    const statementDate = strArg(args, 'statement_date');
    if (!bankAccountId) return toolError('bank_account_id is required');
    if (!statementDate) return toolError('statement_date is required (YYYY-MM-DD)');

    const bad = guardCastableArgs(args, {
      uuid: ['bank_account_id'],
      date: ['statement_date'],
    });
    if (bad) return bad;

    const statementBalance = args.statement_balance;
    if (typeof statementBalance !== 'number' || !Number.isFinite(statementBalance)) {
      return toolError('statement_balance must be a number');
    }

    const dryRun = args.dry_run === true;
    const autoMatch = args.auto_match !== false;
    const complete = args.complete === true;

    // Ownership BEFORE any service call: bank_account_id becomes a foreign key
    // and nothing downstream re-checks the tenant.
    if (!(await bankGlAccountBelongsToCompany(ctx.companyId, bankAccountId))) {
      return toolError(NOT_FOUND);
    }

    // A second in-progress session on one account would claim no transactions
    // (the first holds them all) and read as a reconciliation of nothing.
    // Answered from a READ so it is a pre-write refusal.
    const existing = await getReconciliations(ctx.companyId, bankAccountId);
    const inProgress = existing.find((r) => r.status === 'in_progress');
    if (inProgress) {
      return toolError(
        `A reconciliation is already in progress on this account (id ${inProgress.id}, statement `
        + `date ${inProgress.statementDate}, difference R${inProgress.difference.toFixed(2)}). `
        + 'Complete it or cancel it with cancel_bank_reconciliation before starting another.',
      );
    }

    if (dryRun) {
      // Every guard above has run. The GL side comes from cash.balance.v1's
      // owning service rather than being re-derived here.
      const cash = await getCashBalance(ctx.companyId, statementDate);
      const glBalance = cash.accounts.find((a) => a.accountId === bankAccountId)?.glBalance ?? 0;
      return {
        ...ok({
          dry_run: true,
          bank_account_id: bankAccountId,
          statement_date: statementDate,
          statement_balance: statementBalance,
          gl_balance: glBalance,
          difference: statementBalance - glBalance,
          would_auto_match: autoMatch,
          would_complete_if_balanced: complete,
          note:
            'Nothing was written. The difference shown is against the GL balance BEFORE any '
            + 'matching; the live call reports the difference after matching.',
        }),
        wroteNothing: true,
        billable: false,
      };
    }

    // From here on the request has written. Every failure must RETHROW: the
    // savepoint unwinds on a throw and not on a returned tool error, and a
    // returned error would commit a half-started reconciliation AND free the
    // key for a retry that starts a second one.
    const started = await startReconciliation(
      ctx.companyId, bankAccountId, statementDate, statementBalance, ctx.userId,
    );

    const matchResult = autoMatch
      ? await autoMatchTransactions(ctx.companyId, bankAccountId, started.id)
      : null;

    // Re-read: startReconciliation computed the reconciled balance before any
    // matching, and completeReconciliation checks the CURRENT difference.
    const current = await getReconciliationById(ctx.companyId, started.id);
    const difference = current?.difference ?? started.difference;
    const balanced = Math.abs(difference) < BALANCED_TOLERANCE;
    const matchedCount = current?.matchedCount ?? matchResult?.matched ?? 0;

    // A session that matched NOTHING is trivially "balanced": startReconciliation
    // sets reconciled_balance to gl_balance, so an empty session shows a R0.00
    // difference before anything happens. Production holds exactly one such
    // completed reconciliation — R0.00 difference, zero matched transactions —
    // and in every list and report it is indistinguishable from one that
    // proved the whole account. Completing that is signing off on nothing.
    const provedSomething = matchedCount > 0;
    const completed = complete && balanced && provedSomething
      ? await completeReconciliation(ctx.companyId, started.id, ctx.userId)
      : null;

    return ok({
      dry_run: false,
      reconciliation_id: started.id,
      bank_account_id: bankAccountId,
      statement_date: statementDate,
      statement_balance: statementBalance,
      gl_balance: started.glBalance,
      reconciled_balance: completed?.reconciledBalance ?? current?.reconciledBalance ?? started.reconciledBalance,
      difference,
      balanced,
      status: completed?.status ?? current?.status ?? started.status,
      completed: completed !== null,
      auto_matched: matchResult?.matched ?? 0,
      matched_count: matchedCount,
      still_unmatched: matchResult?.unmatched ?? current?.unmatchedCount ?? 0,
      low_confidence_candidates: matchResult?.candidates.length ?? 0,
      skipped_raced: matchResult?.skippedRaced ?? 0,
      ...(complete && !balanced
        ? {
          note:
            `Not completed: the difference is R${difference.toFixed(2)} and completion requires `
            + 'exactly zero. The session is still in progress with its matches intact — allocate '
            + 'the outstanding transactions, or cancel_bank_reconciliation to release them.',
        }
        : complete && !provedSomething
          ? {
            note:
              'Not completed: the session matched no transactions. It shows a zero difference '
              + 'only because a reconciliation starts at the GL balance, so an empty session '
              + 'balances trivially and would prove nothing. Allocate or import the '
              + 'transactions first, or cancel_bank_reconciliation to release the session.',
          }
          : {}),
    });
  }

tools.input_schema_source:
{
    type: 'object',
    properties: {
      period_start: { type: 'string', format: 'date' },
      period_end: { type: 'string', format: 'date' },
      notes: { type: 'string', description: 'Free text recorded with the lock, e.g. the eFiling reference.' },
      force: {
        type: 'boolean',
        description: 'Lock even though the 15% check fails. Records the decision; it does not make the return correct.',
      },
      ...MUTATION_ARG_SCHEMA,
    },
    required: ['period_start', 'period_end', 'idempotency_key'],
    additionalProperties: false,
  }

tools.handler_source:
async (args, ctx) => {
    // ── PRE-WRITE VALIDATION. Everything that can return toolError is here,
    // before any service that can write has been called. After the write, a
    // failure must THROW so the savepoint rolls it back.
    const period = periodArgs(args);
    if (typeof period === 'string') return toolError(period);
    const bad = guardCastableArgs(args, { date: ['period_start', 'period_end'] });
    if (bad) return bad;

    const existing = await getVatPeriodLock(ctx.companyId, period.start, period.end);
    const report = await getVat201Report(ctx.companyId, period.start, period.end, { detail: 'summary' });

    if (!existing && report.rateCheck.ties === false && args.force !== true) {
      return toolError(
        `This period fails SARS's 15% check: box 1 is out by ${report.rateCheck.outputVariance} and box 15 by ${report.rateCheck.inputVariance}. `
        + 'Read vat_status detail="full" to find which journals, or pass force:true to lock it as it stands.',
      );
    }

    const figures = {
      outputTax: report.totals.outputTax,
      inputTax: report.totals.inputTax,
      netVat: report.totals.netVat,
      postedThrough: report.postedThrough,
    };

    if (args.dry_run === true) {
      return {
        ...ok({
          dryRun: true,
          wouldLock: !existing,
          alreadyLocked: existing,
          figures,
          rateCheck: report.rateCheck,
          excludedRows: report.excludedRows,
        }),
        // Without this the preview is stored under the idempotency key and the
        // real call that follows is served it forever.
        wroteNothing: true,
      };
    }

    const actor = actorForMcp(ctx, 'mcp:lock_vat_period:v1');
    const result = await lockVatPeriod(
      ctx.companyId, period.start, period.end, figures,
      { userId: actor.userId, actorType: actor.actorType, tokenJti: actor.tokenJti },
      strArg(args, 'notes'),
    );

    return {
      ...ok({ locked: result.lock, created: result.created, rateCheck: report.rateCheck }),
      // A lock that already existed wrote nothing, so it must not occupy the
      // key either — the same rule as a dry run.
      ...(result.created ? {} : { wroteNothing: true }),
    };
  }
